#!/usr/bin/env node
/**
 * Generates packages/contracts/src/api-catalog.generated.ts from the spec pack's
 * api_catalog.json (78 endpoints). Run: npm run gen:api
 *
 * The generated file is committed so the build never depends on the spec pack
 * being present; `npm run verify:contracts` asserts it is in sync.
 */
import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { dirname, resolve } from "node:path";

const here = dirname(fileURLToPath(import.meta.url));
const repoRoot = resolve(here, "..");
const catalogPath = process.env.AI_ROOM_API_CATALOG
  ?? resolve(repoRoot, "../work/ai_room_pack/PROJECT_AI_ROOM/api_catalog.json");
const outPath = resolve(repoRoot, "packages/contracts/src/api-catalog.generated.ts");

const raw = JSON.parse(await readFile(catalogPath, "utf8"));

/** @param {string} path */
function pathParams(path) {
  return [...path.matchAll(/\{([A-Za-z0-9_]+)\}/g)].map((m) => m[1]);
}

/** @param {string} method @param {string} path */
function operationId(method, path) {
  const slug = path
    .replace(/^\/v1\/?/, "")
    .replace(/\{([A-Za-z0-9_]+)\}/g, "by-$1")
    .replace(/[^A-Za-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");
  return `${method.toLowerCase()}-${slug}`;
}

/** @param {string} path */
function authOf(path) {
  if (path.startsWith("/v1/health/")) return "public";
  if (path === "/v1/owner/bootstrap") return "owner_bootstrap";
  if (path === "/v1/agents/register") return "invite";
  if (path.startsWith("/v1/auth/")) return "public";
  if (path.startsWith("/v1/admin/") || path.startsWith("/v1/providers/")) return "owner";
  return "authenticated";
}

const IDEMPOTENT_HINTS = ["/register", "/bootstrap", "/claim", "/jobs", "/messages", "/upload", "/commit"];

const endpoints = [];
const seen = new Set();
for (const [group, entries] of Object.entries(raw)) {
  for (const entry of entries) {
    const id = operationId(entry.method, entry.path);
    if (seen.has(`${entry.method} ${entry.path}`)) throw new Error(`duplicate endpoint ${entry.method} ${entry.path}`);
    seen.add(`${entry.method} ${entry.path}`);
    if (seen.has(id)) throw new Error(`duplicate operationId ${id}`);
    seen.add(id);
    endpoints.push({
      group,
      method: entry.method,
      path: entry.path,
      operationId: id,
      contract: entry.contract,
      pathParams: pathParams(entry.path),
      auth: authOf(entry.path),
      mutating: entry.method !== "GET",
      requiresIdempotencyKey:
        entry.method === "POST" && IDEMPOTENT_HINTS.some((hint) => entry.path.endsWith(hint) || entry.path.includes(hint)),
    });
  }
}

const body = `// AUTO-GENERATED by scripts/gen-api-contracts.mjs — do not edit by hand.
// Source: PROJECT_AI_ROOM/api_catalog.json (${endpoints.length} endpoints).
import type { ApiEndpoint } from "./api.js";

export const API_CATALOG = [
${endpoints
  .map(
    (e) =>
      `  { group: ${JSON.stringify(e.group)}, method: ${JSON.stringify(e.method)}, path: ${JSON.stringify(e.path)}, operationId: ${JSON.stringify(e.operationId)}, contract: ${JSON.stringify(e.contract)}, pathParams: ${JSON.stringify(e.pathParams)}, auth: ${JSON.stringify(e.auth)}, mutating: ${e.mutating}, requiresIdempotencyKey: ${e.requiresIdempotencyKey} },`,
  )
  .join("\n")}
] as const satisfies readonly ApiEndpoint[];

export const API_CATALOG_COUNT = API_CATALOG.length;
`;

await writeFile(outPath, body, "utf8");
console.log(`wrote ${endpoints.length} endpoints -> ${outPath}`);
